  const resolveActor = (req: Request, res: Response, next: NextFunction) => {
    const header = req.get('X-Actor-Id');
    if (!header || header.trim() === '') {
      res.status(401).json({ error: 'X-Actor-Id header required' });
      return;
    }
    const row = db
