    res.locals.tenant = { id: row.tenant_id, slug: row.slug, name: row.name, iana_timezone: row.iana_timezone } satisfies TenantRow;
    next();
  };

  const actor = (req: Request): { admin: AdminRow; tenant: TenantRow } => ({
    admin: res.locals... // need res, not req
  });
